package dev.eugheist.ttmodern;
@net.neoforged.fml.common.EventBusSubscriber(modid="ttinkerer",bus=net.neoforged.fml.common.EventBusSubscriber.Bus.MOD,value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class AwakenedWings {
 static net.minecraft.client.model.HumanoidModel<net.minecraft.world.entity.LivingEntity> model;
 static net.minecraft.client.model.HumanoidModel<net.minecraft.world.entity.LivingEntity> model(){if(model==null){var mesh=net.minecraft.client.model.HumanoidModel.createMesh(new net.minecraft.client.model.geom.builders.CubeDeformation(1),0);var body=mesh.getRoot().getChild("body");body.addOrReplaceChild("wing1",net.minecraft.client.model.geom.builders.CubeListBuilder.create().texOffs(16,-12).addBox(0,0,0,0,7,12),net.minecraft.client.model.geom.PartPose.offsetAndRotation(-2,1,2,0,-.6108652f,0));body.addOrReplaceChild("wing2",net.minecraft.client.model.geom.builders.CubeListBuilder.create().texOffs(16,-12).addBox(.1f,0,0,0,7,12),net.minecraft.client.model.geom.PartPose.offsetAndRotation(2,1,2,0,.4468043f,0));model=new net.minecraft.client.model.HumanoidModel<>(net.minecraft.client.model.geom.builders.LayerDefinition.create(mesh,64,32).bakeRoot());}return model;}
 @net.neoforged.bus.api.SubscribeEvent public static void register(net.neoforged.neoforge.client.extensions.common.RegisterClientExtensionsEvent event){if(!KamiStartupConfig.enabled())return ;event.registerItem(new net.neoforged.neoforge.client.extensions.common.IClientItemExtensions(){@Override public net.minecraft.client.model.HumanoidModel<?> getHumanoidArmorModel(net.minecraft.world.entity.LivingEntity entity,net.minecraft.world.item.ItemStack stack,net.minecraft.world.entity.EquipmentSlot slot,net.minecraft.client.model.HumanoidModel<?> original){var result=model();var left=result.body.getChild("wing1");var right=result.body.getChild("wing2");left.yRot=-.6108652f;right.yRot=.4468043f;if(entity instanceof net.minecraft.world.entity.player.Player player&&player.getAbilities().flying){left.yRot=(float)((Math.sin(entity.tickCount)+1)*(Math.PI/180)*15-.6108651757240295);right.yRot=-left.yRot;}return result;}},AwakenedChest.ITEM.get());}
}
